Set tStatus = $$$OK
Try {
	If $IsObject(..RecCLCC) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecCLCC).PutObject(pIOStream,..RecCLCC,0)
		If $$$ISERR(tStatus) Quit
	}
}
Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus

